const inputs = $input.first().json.inputs;
const cleaned = inputs.map(item => ({
  ...item,
  properties: Object.fromEntries(
    Object.entries(item.properties).filter(([_, v]) => v !== null && v !== undefined && v !== '')
  )
}));
return [{ json: { inputs: cleaned } }];

